-- Companions: vanilla loot where Forever's own loot lacks it: the classic dungeons and raids (Onyxia and Naxxramas are level 80
-- in the source and left out), their scripted and summoned creatures (the Ring of Law, Theldren...), the world bosses and the
-- chests there. Source: TrinityCore TDB 335.26091 (2026-09-09). Never replaces Forever's loot, only adds what its lists lack:
--   items: missing ones at their TDB chance; a group Forever has none of is copied as it is (groups 200+), else each missing
--   item gets the chance it has in the TDB group;
--   shared lists: a copy (9500000 + TDB id) when Forever has none of its items, else a list of the missing ones (9600000+),
--   each at the chance it has for one roll of the TDB list; a reference row's GroupId keeps its meaning (roll only that
--   group of the list);
--   creatures without a loot list in Forever get one (LootID = their entry, or 9700000 + entry).
-- Items the Forever client lacks are created by the hotfixes file 2026_10_26_90_hotfixes_companions_vanilla_items.sql.
-- Generated: re-running removes and re-adds the same rows.
DELETE FROM `creature_loot_template` WHERE `Comment` = 'companions: vanilla loot';
DELETE FROM `gameobject_loot_template` WHERE `Comment` = 'companions: vanilla loot';
DELETE FROM `reference_loot_template` WHERE `Entry` BETWEEN 9500000 AND 9699999;
UPDATE `creature_template_difficulty` SET `LootID` = 10076 WHERE `Entry` = 10076 AND `LootID` = 0; -- High Priestess of Thaurissan
UPDATE `creature_template_difficulty` SET `LootID` = 10475 WHERE `Entry` = 10475 AND `LootID` = 0; -- Scholomance Student
UPDATE `creature_template_difficulty` SET `LootID` = 14401 WHERE `Entry` = 14401 AND `LootID` = 0; -- Master Elemental Shaper Krixix
